INSERT OR REPLACE INTO content (key, value, updated_at) VALUES ('i18n', '{"nav.map":["Map","Peta"],"nav.profile":["Profile","Profil"],"nav.path":["Path","Jejak"],"nav.work":["Work","Karya"],"nav.stack":["Stack","Stack"],"nav.contact":["Contact","Kontak"],"hero.thesis":["Most of what I build has <b>no public URL</b>. They are internal systems for the Indonesian state — payroll, risk, correspondence, official letters. So this page does not pretend to be a product gallery. It reconstructs them as drawings.","Sebagian besar yang saya bangun <b>tidak punya URL publik</b>. Semuanya sistem internal negara — kepegawaian, risiko, korespondensi, surat dinas. Jadi halaman ini tidak berpura-pura jadi galeri produk, melainkan merekonstruksinya sebagai gambar teknik."],"map.title":["Fig. 1 — Systems built &amp; maintained","Gbr. 1 — Sistem yang dibangun &amp; dirawat"],"map.hint":["Select a node to open its drawing","Pilih node untuk membuka gambarnya"],"map.live":["In production","Berjalan di produksi"],"map.archived":["Academic / archived","Akademik / arsip"],"map.note":["Screens redrawn · figures withheld","Layar digambar ulang · angka disamarkan"],"h.profile":["Profile","Profil"],"p.slot":["Portrait slot<br>3:4 · 900×1200","Slot foto<br>3:4 · 900×1200"],"p.b1":["I write software that civil servants open every morning. Attendance, performance reviews, official letters, periodic reports from every state-owned enterprise — unglamorous work, with the quiet requirement that it cannot be down.","Saya menulis perangkat lunak yang dibuka aparatur sipil setiap pagi. Presensi, penilaian kinerja, surat dinas, laporan berkala dari seluruh BUMN — pekerjaan yang jauh dari glamor, dengan satu syarat yang tak pernah diucapkan: tidak boleh mati."],"p.b2":["I came into development sideways: my first role was test engineer at Vidio, breaking mobile apps for a living. That order turned out to be useful. I still think in edge cases first, and I write the regression path before I write the feature.","Saya masuk ke pengembangan lewat pintu samping: peran pertama saya test engineer di Vidio, kerjanya membongkar aplikasi mobile orang lain. Urutan itu ternyata berguna. Saya masih berpikir dari edge case dulu, dan menulis jalur regresi sebelum menulis fiturnya."],"k.base":["Base","Domisili"],"k.disc":["Discipline","Bidang"],"v.disc":["Full-stack · Government systems","Full-stack · Sistem pemerintahan"],"k.edu":["Education","Pendidikan"],"v.edu":["STMIK Jayakarta — B.Eng, Informatics","STMIK Jayakarta — S.Kom, Teknik Informatika"],"k.gpa":["GPA","IPK"],"k.lang":["Languages","Bahasa"],"v.lang":["Indonesian (native) · English (conversational)","Indonesia (bahasa ibu) · Inggris (percakapan)"],"k.method":["Practice","Praktik"],"v.method":["Agile · Monolithic architecture · AI-assisted development","Agile · Arsitektur monolitik · Pengembangan dibantu AI"],"h.path":["Path","Jejak"],"h.pathsub":["Two concurrent postings since 2024","Dua penempatan bersamaan sejak 2024"],"g.emp":["Employment","Pekerjaan"],"g.prog":["Programs","Program"],"g.edu":["Education","Pendidikan"],"r1.t":["Fullstack Developer","Fullstack Developer"],"r1.org":["PT Sinergi Informatika Semen Indonesia · 2024 → present","PT Sinergi Informatika Semen Indonesia · 2024 → sekarang"],"r2.org":["Kementerian BUMN · Mar 2023 – Dec 2023","Kementerian BUMN · Mar 2023 – Des 2023"],"r3.org":["PT Vidio Dot Com · 2021 – 2022","PT Vidio Dot Com · 2021 – 2022"],"r1.a":["Built and shipped the ministry''s iOS attendance app in Swift — geofenced check-in, employee directory, meeting QR — now in daily use by staff.","Membangun dan merilis aplikasi presensi iOS kementerian dengan Swift — presensi dengan geofence, direktori pegawai, QR rapat — kini dipakai harian oleh staf."],"r1.b":["Delivered new features into a long-running production system without downtime, and without the rewrite it was assumed to need.","Merilis fitur baru ke sistem produksi yang sudah lama berjalan tanpa downtime, dan tanpa rewrite yang selama ini dianggap wajib."],"r1.c":["Moved dashboard aggregations into PostgreSQL views, so the executive screen reads results instead of recomputing them on every load.","Memindahkan agregasi dashboard ke PostgreSQL view, sehingga layar eksekutif membaca hasil, bukan menghitung ulang tiap kali dimuat."],"r2.t":["Junior Web Programmer","Junior Web Programmer"],"r2.a":["Developed and maintained both internal and external applications of Kementerian BUMN, primarily using the Laravel framework.","Mengembangkan dan merawat aplikasi internal maupun eksternal Kementerian BUMN, terutama dengan Laravel."],"r2.b":["Modelled data in PostgreSQL with functions, views and relations, so reporting stayed fast as filings accumulated.","Memodelkan data di PostgreSQL dengan function, view, dan relasi, sehingga pelaporan tetap cepat seiring berkas menumpuk."],"r2.c":["Watched the critical paths — submission, verification, approval — and hardened the screens that stop work when they break.","Memantau jalur kritis — pengajuan, verifikasi, persetujuan — dan memperkuat layar yang, begitu rusak, menghentikan pekerjaan."],"r3.t":["Test Engineer","Test Engineer"],"r3.a":["Ran release cycles on Vidio''s mobile apps — manual, regression, sanity and smoke passes before each build shipped.","Menjalankan siklus rilis aplikasi mobile Vidio — uji manual, regresi, sanity, dan smoke sebelum tiap build dirilis."],"r3.b":["Turned acceptance criteria into automated scenarios with AppiumLibrary, so the same checks ran every release instead of by hand.","Mengubah kriteria penerimaan menjadi skenario otomatis dengan AppiumLibrary, sehingga pemeriksaan yang sama berjalan tiap rilis, bukan manual."],"r3.c":["Filed the defects each cycle produced, with the reproduction steps developers needed to act on them.","Membuat laporan bug dari tiap siklus, lengkap dengan langkah reproduksi yang dibutuhkan developer."],"h.work":["Register of systems","Daftar sistem"],"c.system":["System","Sistem"],"c.runtime":["Runtime","Runtime"],"c.domain":["Domain","Domain"],"c.year":["Year","Tahun"],"h.stack":["Stack, by layer","Stack, per lapisan"],"d.core":["Daily / production","Harian / produksi"],"d.work":["Working knowledge","Cukup menguasai"],"d.learn":["Learning","Sedang dipelajari"],"h.qa":["I started by breaking things","Sebelum membangun, saya membongkar"],"q.b1":["Before I shipped features I tested other people''s. Six months at Vidio running release cycles on the mobile apps taught me what a defect looks like before a user finds it.","Sebelum merilis fitur sendiri, saya menguji fitur orang lain. Enam bulan di Vidio menjalankan siklus rilis aplikasi mobile mengajari saya mengenali bug sebelum pengguna menemukannya."],"q.b2":["It is the reason my Laravel work carries verification steps in the user story, not just an acceptance line.","Itu sebabnya user story pada pekerjaan Laravel saya memuat langkah verifikasi, bukan sekadar satu baris kriteria penerimaan."],"q.s1":["Manual","Manual"],"q.d1":["Exploratory passes against the story''s acceptance criteria.","Uji eksploratif terhadap kriteria penerimaan user story."],"q.s2":["Automation","Otomasi"],"q.d2":["Scenarios scripted and run with AppiumLibrary.","Skenario ditulis sebagai skrip lalu dijalankan dengan AppiumLibrary."],"q.s3":["Regression","Regresi"],"q.d3":["Every prior path re-run before a release is tagged.","Semua jalur lama diuji ulang sebelum rilis ditandai."],"q.s4":["Sanity &amp; smoke","Sanity &amp; smoke"],"q.d4":["Fast gates on the build — does it start, does the core path hold.","Pemeriksaan cepat pada build — apakah aplikasinya jalan, apakah jalur intinya bertahan."],"h.cred":["Certified","Sertifikasi"],"h.contact":["Send a brief","Kirim kebutuhan Anda"],"f.name":["Name","Nama"],"f.email":["Email","Email"],"f.msg":["What do you need built?","Apa yang perlu dibangun?"],"f.send":["Transmit","Kirim"],"f.ok":["Received","Diterima"],"f.okb":["I read everything that comes in and reply within two working days.","Semua yang masuk saya baca dan saya balas dalam dua hari kerja."],"t.foot":["Built in Jakarta. No tracking beyond a page counter.","Dibuat di Jakarta. Tanpa pelacakan selain penghitung kunjungan."],"dr.about":["About","Tentang"],"dr.hi":["What it does","Fungsinya"],"dr.screens":["Screens","Layar"],"dr.org":["Client","Klien"],"dr.role":["Role","Peran"],"dr.status":["Status","Status"],"dr.live":["In production","Berjalan di produksi"],"dr.idle":["Archived","Arsip"],"dr.year":["In service","Masa operasi"],"dr.pdf":["Open full portfolio (PDF)","Buka portofolio lengkap (PDF)"],"t.present":["present","sekarang"],"dr.fig":["Fig. — interface schematic, redrawn","Gbr. — skema antarmuka, digambar ulang"],"h.services":["What I can build for you","Yang bisa saya bangun untuk Anda"],"h.servicessub":["Framed as the problem, not the stack","Dirumuskan sebagai masalah, bukan teknologi"],"h.how":["Working together","Cara kita bekerja sama"],"dr.repo":["Read the source","Baca kodenya"],"nav.services":["Services","Layanan"]}', 1786000200);
